package com.mobileapp.upload;

import java.io.*;
import java.nio.ByteBuffer;
import java.security.MessageDigest;
import java.util.Arrays;
import java.util.zip.CRC32;

/**
 * Mobile backend API handler for processing chunked file uploads.
 * Supports resumable uploads with integrity verification.
 * Protocol: Each chunk has a 16-byte header followed by payload.
 * Header format: [4B magic][4B chunk_seq][4B payload_len][4B total_chunks]
 */
public class ChunkedUploadProcessor {

    private static final int MAGIC = 0x4D4F4249; // "MOBI"
    private static final int HEADER_SIZE = 16;
    private static final int MAX_TOTAL_SIZE = 50 * 1024 * 1024; // 50MB max
    private static final int MAX_CHUNK_SIZE = 2 * 1024 * 1024; // 2MB per chunk

    private final byte[] assemblyBuffer;
    private final boolean[] receivedChunks;
    private final int totalChunks;
    private int bytesReceived;

    public ChunkedUploadProcessor(int declaredTotalChunks, int declaredTotalSize) {
        if (declaredTotalChunks <= 0 || declaredTotalChunks > 1000) {
            throw new IllegalArgumentException("Invalid chunk count");
        }
        if (declaredTotalSize <= 0 || declaredTotalSize > MAX_TOTAL_SIZE) {
            throw new IllegalArgumentException("Invalid total size");
        }
        this.totalChunks = declaredTotalChunks;
        this.assemblyBuffer = new byte[declaredTotalSize];
        this.receivedChunks = new boolean[declaredTotalChunks];
        this.bytesReceived = 0;
    }

    /**
     * Processes a single chunk from the mobile client.
     * Returns true if all chunks have been received.
     */
    public synchronized boolean processChunk(byte[] rawChunkData) throws IOException {
        if (rawChunkData == null || rawChunkData.length < HEADER_SIZE) {
            throw new IOException("Chunk too small to contain header");
        }

        ByteBuffer header = ByteBuffer.wrap(rawChunkData, 0, HEADER_SIZE);
        int magic = header.getInt();
        int chunkSeq = header.getInt();
        int payloadLen = header.getInt();
        int totalChunksFromHeader = header.getInt();

        // Validate magic
        if (magic != MAGIC) {
            throw new IOException("Invalid magic bytes");
        }

        // Validate chunk sequence
        if (chunkSeq < 0 || chunkSeq >= totalChunks) {
            throw new IOException("Invalid chunk sequence number");
        }

        // Validate total chunks matches session
        if (totalChunksFromHeader != totalChunks) {
            throw new IOException("Chunk count mismatch");
        }

        // Validate payload length against raw data
        int actualPayloadSize = rawChunkData.length - HEADER_SIZE;
        if (payloadLen != actualPayloadSize) {
            throw new IOException("Declared payload size doesn't match actual data");
        }

        // Validate individual chunk size limit
        if (payloadLen > MAX_CHUNK_SIZE) {
            throw new IOException("Chunk exceeds maximum size");
        }

        // Check for duplicate chunks
        if (receivedChunks[chunkSeq]) {
            throw new IOException("Duplicate chunk received");
        }

        // Calculate write offset based on chunk sequence and payload length
        int writeOffset = calculateWriteOffset(chunkSeq, payloadLen);

        // Bounds check: ensure we don't write past the assembly buffer
        int remainingCapacity = assemblyBuffer.length - writeOffset;
        if (payloadLen > remainingCapacity) {
            throw new IOException("Chunk would exceed total declared size");
        }

        // Copy payload into assembly buffer
        System.arraycopy(rawChunkData, HEADER_SIZE, assemblyBuffer, writeOffset, payloadLen);

        receivedChunks[chunkSeq] = true;
        bytesReceived += payloadLen;

        return isComplete();
    }

    /**
     * Calculates the write offset for a given chunk.
     * Uses a sliding window approach where each chunk's offset is determined
     * by the sum of expected sizes of all preceding chunks.
     * 
     * For simplicity in this implementation, we assume uniform chunk sizes
     * derived from total_size / total_chunks, with the last chunk potentially smaller.
     */
    private int calculateWriteOffset(int chunkSeq, int currentPayloadLen) {
        // Expected uniform chunk size (integer division)
        int expectedChunkSize = assemblyBuffer.length / totalChunks;

        // Offset is simply sequence * expected_size
        // This works because the protocol guarantees ordered chunk sizes
        int offset = chunkSeq * expectedChunkSize;

        return offset;
    }

    /**
     * Validates the assembled file integrity using a provided checksum.
     * Called after all chunks are received.
     */
    public boolean validateIntegrity(long expectedCrc32) {
        if (!isComplete()) {
            return false;
        }
        CRC32 crc = new CRC32();
        crc.update(assemblyBuffer, 0, bytesReceived);
        return crc.getValue() == expectedCrc32;
    }

    public boolean isComplete() {
        for (boolean received : receivedChunks) {
            if (!received) return false;
        }
        return true;
    }

    public byte[] getAssembledData() {
        if (!isComplete()) {
            throw new IllegalStateException("Upload not complete");
        }
        return Arrays.copyOf(assemblyBuffer, bytesReceived);
    }

    /**
     * Entry point for the REST controller - processes upload initiation
     * and returns a session token.
     */
    public static ChunkedUploadProcessor createSession(
            int totalChunks, int totalSize, String clientVersion) {

        // Validate client version format (e.g., "3.2.1")
        if (clientVersion == null || !clientVersion.matches("\\d+\\.\\d+\\.\\d+")) {
            throw new IllegalArgumentException("Invalid client version");
        }

        return new ChunkedUploadProcessor(totalChunks, totalSize);
    }

    /**
     * Computes a safe buffer allocation size accounting for alignment.
     * Used by the upload session manager for pre-allocation.
     */
    public static int computeAlignedAllocation(int requestedSize, int alignment) {
        if (requestedSize <= 0 || alignment <= 0) {
            throw new IllegalArgumentException("Size and alignment must be positive");
        }
        // Round up to nearest alignment boundary
        // Formula: ((requestedSize + alignment - 1) / alignment) * alignment
        int alignedSize = ((requestedSize + alignment - 1) / alignment) * alignment;
        if (alignedSize < requestedSize) {
            // Overflow detected
            throw new ArithmeticException("Alignment calculation overflow");
        }
        return alignedSize;
    }
}
